import calendar
from datetime import date


def nth_weekday(year, month, weekday, n):
    """Return the ISO date of the n-th `weekday` in the given month.

    weekday: 0 = Monday ... 6 = Sunday
    n: 1..5 for first..fifth occurrence, -1 for the last occurrence.
    Raises ValueError if no such occurrence exists (or on bad arguments).
    """
    if not isinstance(weekday, int) or isinstance(weekday, bool):
        raise ValueError("weekday must be an int in 0..6")
    if not isinstance(n, int) or isinstance(n, bool):
        raise ValueError("n must be an int in 1..5 or -1")
    if not 0 <= weekday <= 6:
        raise ValueError("weekday must be in 0..6")
    if n != -1 and not 1 <= n <= 5:
        raise ValueError("n must be 1..5 or -1")
    if not 1 <= month <= 12:
        raise ValueError("month must be in 1..12")

    first = date(year, month, 1)                 # validates year/month
    days_in_month = calendar.monthrange(year, month)[1]

    # Day-of-month of the first occurrence of `weekday`.
    first_occ = 1 + (weekday - first.weekday()) % 7

    if n == -1:
        day = first_occ + ((days_in_month - first_occ) // 7) * 7
    else:
        day = first_occ + 7 * (n - 1)
        if day > days_in_month:
            raise ValueError(
                "no occurrence %d of weekday %d in %04d-%02d" % (n, weekday, year, month)
            )

    return date(year, month, day).isoformat()
